using System;using System.IO;using System.Collections.Generic;using SolidWorks.Interop.sldworks;
public static class RigMotion {
static ISldWorks sw;static IModelDoc2 d;static IAssemblyDoc a;static IMathUtility math;
static void Select(IComponent2 c){d.ClearSelection2(true);if(!c.Select4(false,null,false))throw new Exception("select "+c.Name2);}
static void Fix(IComponent2 c,bool fix){Select(c);if(fix)a.FixComponent();else a.UnfixComponent();}
static IComponent2 C(string n){var c=a.GetComponentByName(n) as IComponent2;if(c==null)throw new Exception(n);return c;}
static IFace2 Face(IComponent2 c,int axis,double coord,bool cylinder){var pd=(IPartDoc)c.GetModelDoc2();IFace2 best=null;double area=0;foreach(object b in (object[])pd.GetBodies2(0,false))foreach(object o in (object[])((IBody2)b).GetFaces()){var f=(IFace2)o;var s=(ISurface)f.GetSurface();if(cylinder){if(!s.IsCylinder())continue;var p=(double[])s.CylinderParams;if(Math.Abs(p[6]-coord)>1e-7||Math.Abs(p[3+axis])<.999)continue;bool center=true;for(int k=0;k<3;k++)if(k!=axis&&Math.Abs(p[k])>1e-7)center=false;if(!center)continue;}else{if(!s.IsPlane())continue;var p=(double[])s.PlaneParams;if(Math.Abs(p[axis])<.999||Math.Abs(p[3+axis]-coord)>1e-7)continue;}if(f.GetArea()>area){best=f;area=f.GetArea();}}if(best==null)throw new Exception("face "+c.Name2);return (IFace2)c.GetCorrespondingEntity(best);}
static void Mate(object one,object two,int type,double dist,string name){d.ClearSelection2(true);if(one is IComponent2){((IComponent2)one).Select4(false,null,false);((IComponent2)two).Select4(true,null,false);}else{((IEntity)one).Select4(false,null);((IEntity)two).Select4(true,null);}int e=0;var m=a.AddMate5(type,2,false,dist,0,0,0,0,0,0,0,false,false,0,out e);if(m==null||e!=1)throw new Exception(name+" mate="+e);d.ClearSelection2(true);Console.WriteLine("Added "+name);}
static void Check(){for(var f=(IFeature)d.FirstFeature();f!=null;f=(IFeature)f.GetNextFeature())if(f.GetTypeName2()=="MateGroup")for(var s=(IFeature)f.GetFirstSubFeature();s!=null;s=(IFeature)s.GetNextSubFeature()){bool w;int e=s.GetErrorCode2(out w);if(e!=0&&!s.IsSuppressed())throw new Exception("Mate error "+s.Name+" "+e);}}
public static void Run(object app,string root){sw=(ISldWorks)app;math=(IMathUtility)sw.GetMathUtility();string path=Path.Combine(root,"solid_3mm","Motion-3mm.SLDASM");if(File.Exists(path))throw new Exception("Motion-3mm.SLDASM already exists; preserve or rename it before building a fresh rig.");File.Copy(Path.Combine(root,"solid_3mm","Assem1.SLDASM"),path);int e=0,w=0;d=sw.OpenDoc6(path,2,1,"",ref e,ref w) as IModelDoc2;if(d==null||e!=0)throw new Exception("Open "+e);sw.ActivateDoc3(d.GetTitle(),false,1,ref e);a=(IAssemblyDoc)d;a.EnableAssemblyRebuild=false;a.ResolveAllLightWeightComponents(false);
var transforms=new Dictionary<string,double[]>();foreach(object o in (object[])a.GetComponents(false)){var c=(IComponent2)o;transforms[c.Name2]=(double[])c.Transform2.ArrayData;Fix(c,true);}
var remove=new List<IFeature>();for(var f=(IFeature)d.FirstFeature();f!=null;f=(IFeature)f.GetNextFeature())if(f.GetTypeName2()=="MateGroup")for(var s=(IFeature)f.GetFirstSubFeature();s!=null;s=(IFeature)s.GetNextSubFeature()){var m=s.GetSpecificFeature2() as IMate2;if(m==null)continue;bool gondola=false;for(int i=0;i<m.GetMateEntityCount();i++){var c=m.MateEntity(i).ReferenceComponent;if(c!=null&&Path.GetFileName(c.GetPathName())=="gondola.SLDPRT")gondola=true;}if(!gondola||s.Name=="Distance2")remove.Add(s);}
var hang=new List<IFeature>();for(var f=(IFeature)d.FirstFeature();f!=null;f=(IFeature)f.GetNextFeature())if(f.GetTypeName2()=="MateGroup")for(var mf=(IFeature)f.GetFirstSubFeature();mf!=null;mf=(IFeature)mf.GetNextSubFeature())if(mf.GetSpecificFeature2() is IMate2&&!remove.Contains(mf)){mf.SetSuppression2(0,2,null);hang.Add(mf);}
foreach(var f in remove){d.ClearSelection2(true);f.Select2(false,0);if(!d.Extension.DeleteSelection2(0))throw new Exception("Delete "+f.Name);}
foreach(object o in (object[])a.GetComponents(false)){var c=(IComponent2)o;c.Transform2=(MathTransform)math.CreateTransform(transforms[c.Name2]);}
var wheel=C("wheeel-1");
foreach(object o in (object[])a.GetComponents(false)){var c=(IComponent2)o;string file=Path.GetFileName(c.GetPathName());bool rotor=c.Name2=="wheeel-2"||file=="gear0.SLDPRT"||file=="gondola_dowel_3mm.SLDPRT"||file=="bearing_collar_3mm.SLDPRT"||file=="kugellager.SLDPRT";if(rotor){Fix(c,false);Mate(wheel,c,16,0,"Rotor_glued_"+c.Name2);}if(file=="gondola.SLDPRT")Fix(c,false);}
foreach(var hf in hang)hf.SetSuppression2(1,2,null);
Fix(wheel,false);Mate(Face(wheel,0,.00755,true),Face(C("rod-1"),2,.005,true),1,0,"Wheel_main_axis_FREE_ROTATION");Mate(Face(wheel,0,0,false),Face(C("rod-1"),2,0,false),5,.005,"Wheel_axial_position");

var pin=C("21-1");Fix(pin,false);Mate(Face(pin,2,.0015,true),Face(C("motor_N20_3mm_Dshaft-2"),2,.0015,true),1,0,"Pinion_motor_axis_FREE_ROTATION");Mate(Face(pin,2,.003,false),Face(C("wheeel-2"),0,.003,false),0,0,"Pinion_axial_position");
d.ClearSelection2(true);var sd=(SelectData)((ISelectionMgr)d.SelectionManager).CreateSelectData();sd.Mark=1;((IEntity)Face(wheel,0,.00755,true)).Select4(false,sd);((IEntity)Face(pin,2,.0015,true)).Select4(true,sd);int ge=0;var gm=a.AddMate5(10,1,false,0,0,0,.025,.060,0,0,0,false,false,0,out ge);if(gm==null||ge!=1)throw new Exception("Gear "+ge);
d.ClearSelection2(true);d.ForceRebuild3(false);Check();Console.WriteLine("RIG READY");int se=0,ss=0;if(!d.Save3(1,ref se,ref ss)||se!=0||ss!=0)throw new Exception("Save "+se+" "+ss);d.ShowNamedView2("",7);d.ViewZoomtofit2();d.GraphicsRedraw2();Console.WriteLine("Saved "+path);
}}
